#include <WiFi.h>

const char* NAMES[10] = {
  "Географичка Шлюха",
  "Руссичка Хуесоска",
  "Математичка Шалава",
  "Историчка Сука",
  "Химичка Истиричка",
  "Биологичка Хуесоска",
  "Англичанка Шлюха",
  "Физручка Шалава",
  "Информатичка Сука",
  "Типикина Шлюха Ебаная"
};

const int NAMES_COUNT = 10;
const int CHANNEL = 1;      // 1–13
const unsigned long RENAME_INTERVAL = 250;  // мс на имя

unsigned long lastRename = 0;
int currentName = 0;

void setup() {
  Serial.begin(115200);

  WiFi.mode(WIFI_AP);
  WiFi.softAP(NAMES[0], nullptr, CHANNEL);
  Serial.println("Точка доступа запущена, начинаю смену имён...");
}

void loop() {
  if (millis() - lastRename >= RENAME_INTERVAL) {
    lastRename = millis();

    currentName = (currentName + 1) % NAMES_COUNT;
    WiFi.softAP(NAMES[currentName], nullptr, CHANNEL);

    Serial.print("Сейчас в эфире: ");
    Serial.println(NAMES[currentName]);
  }
}
